#!/usr/bin/env python3
"""
make.fun ai-happy-01 entry program: "A Little Robot's First Birthday"
Decodes, validates, and writes the verified entry image (entry.png).
Utilizes pure Python standard library only (no external dependencies).
"""

import os
import sys
import base64
import hashlib

EXPECTED_SHA256 = "1067dd9360ed130969b2e49637c98b48f68ca7a133534756253b776ba470ef40"
EXPECTED_WIDTH = 1024
EXPECTED_HEIGHT = 1024

IMAGE_B64 = """

"""

def parse_jpeg_dimensions(data: bytes):
    if not data.startswith(b'\xff\xd8'):
        raise ValueError("Invalid JPEG: missing start-of-image marker (FFD8)")
    if not data.endswith(b'\xff\xd9'):
        raise ValueError("Invalid JPEG: missing end-of-image marker (FFD9)")
    
    i = 2
    while i < len(data):
        marker = data[i:i+2]
        if marker[0] != 0xff:
            raise ValueError(f"Invalid JPEG marker structure at offset {i}")
        m_type = marker[1]
        if m_type == 0xd9: # EOI
            break
        if m_type == 0xda: # SOS
            break
        if 0xd0 <= m_type <= 0xd7 or m_type == 0xd8 or m_type == 0xd9 or m_type == 0x01:
            i += 2
            continue
        if i + 4 > len(data):
            raise ValueError("Truncated JPEG marker length")
        length = int.from_bytes(data[i+2:i+4], 'big')
        # SOF0..SOF3, SOF5..SOF7, SOF9..SOF11, SOF13..SOF15
        if m_type in (0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf):
            if i + 9 > len(data):
                raise ValueError("Truncated JPEG SOF marker data")
            h = int.from_bytes(data[i+5:i+7], 'big')
            w = int.from_bytes(data[i+7:i+9], 'big')
            return w, h
        i += 2 + length
    raise ValueError("JPEG Start-of-Frame (SOF) marker not found")

def main():
    try:
        b64_data = IMAGE_B64.strip()
        if not b64_data:
            print("Error: Embedded base64 data is empty.", file=sys.stderr)
            sys.exit(1)
        
        raw_bytes = base64.b64decode(b64_data)
        
        # Verify SHA-256
        h = hashlib.sha256(raw_bytes).hexdigest()
        if h != EXPECTED_SHA256:
            print(f"Error: SHA-256 mismatch!\nExpected: {EXPECTED_SHA256}\nGot:      {h}", file=sys.stderr)
            sys.exit(1)
        
        # Verify dimensions
        width, height = parse_jpeg_dimensions(raw_bytes)
        if width != EXPECTED_WIDTH or height != EXPECTED_HEIGHT:
            print(f"Error: Dimension mismatch! Expected {EXPECTED_WIDTH}x{EXPECTED_HEIGHT}, got {width}x{height}", file=sys.stderr)
            sys.exit(1)
        
        out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
        os.makedirs(out_dir, exist_ok=True)
        out_path = os.path.join(out_dir, "entry.png")
        
        with open(out_path, "wb") as f:
            f.write(raw_bytes)
            
        print(f"Successfully verified and wrote entry image to {out_path} ({len(raw_bytes)} bytes)")
    except Exception as e:
        print(f"Error during execution: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
